-- 인터페이스에 페이징을 더한다

public interface MemberRepositoryCustom {
    List<MemberTeamDto> search(MemberSearchCondition cond);
    Page<MemberTeamDto> searchPageSimple(MemberSearchCondition cond,
                                         Pageable pageable);
}


-- 구현

@Override
public Page<MemberTeamDto> searchPageSimple(MemberSearchCondition cond,
                                            Pageable pageable) {
    BooleanExpression predicate = Expressions.allOf(
            usernameEq(cond.getUsername()),
            teamNameEq(cond.getTeamName()),
            ageBetween(cond.getAgeGoe(), cond.getAgeLoe()));

    List<MemberTeamDto> content = queryFactory
            .select(new QMemberTeamDto(
                    member.id, member.username, member.age,
                    team.id, team.name))
            .from(member)
            .leftJoin(member.team, team)
            .where(predicate)
            .orderBy(member.id.asc())
            .offset(pageable.getOffset())
            .limit(pageable.getPageSize())
            .fetch();

    Long total = queryFactory
            .select(member.count())
            .from(member)
            .leftJoin(member.team, team)
            .where(predicate)
            .fetchOne();

    return new PageImpl<>(content, pageable, total == null ? 0 : total);
}

