@Override
public Page<TeamStat> statsPageOld(Pageable pageable) {
    QueryResults<TeamStat> results = queryFactory
            .select(new QTeamStat(team.name, member.count(),
                    member.age.avg()))
            .from(member)
            .join(member.team, team)
            .groupBy(team.name)
            .offset(pageable.getOffset())
            .limit(pageable.getPageSize())
            .fetchResults();

    return new PageImpl<>(results.getResults(), pageable,
            results.getTotal());
}

